# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        span = Span(9 * 60 + 2, 17 * 60 + 12)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_up_and_down(self):
        span = Span(9 * 60 + 7, 10 * 60 + 38)
        self.assertEqual(
            round_spans([span], 15),
            ["09:00-10:45 (1h 45m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 240)]
        self.assertEqual(len(round_spans(spans, 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
